package org.example.api;

public class Service {
    public void put(String key) {
        assert key != null;
        System.out.println(key);
    }
}

package org.example.api;

public class Service {
    public Service(int size) {
        assert size >= 0 : "negative size";
    }

    protected void put(String key) {
        assert !key.isEmpty();
    }
}

package org.example.api;

public class Service {
    public void put(String key) {
        int length = key == null ? 0 : key.length();
        assert length >= 0;
    }

    void internal(String key) {
        assert key != null;
    }

    private void helper(String key) {
        assert key != null;
    }
}

package org.example.internal;

public class Service {
    public void put(String key) {
        assert key != null;
    }
}
